use std::{fs,collections::{BTreeMap,BTreeSet},os::unix::fs::MetadataExt};use serde_json::{Value,json};use sha2::{Sha256,Digest};
const R:&str="/home/ubuntu/src/zopro-perf-work/two-bank-sdk177";
const PRIOR:&str="/home/ubuntu/src/zopro-perf-work/g2-coordinate-leaf-profile177/proof-sha256-after-profile.json";
fn read(p:&str)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(n:&str,v:Value){fs::write(format!("{R}/{n}"),serde_json::to_vec_pretty(&v).unwrap()).unwrap();}
fn med(mut x:Vec<f64>)->f64{x.sort_by(f64::total_cmp);assert!(x.len()%2==1);x[x.len()/2]}
fn receipt(dir:&str,step:&Value)->f64{let e=read(&format!("{dir}/exit.json"));assert_eq!(e["returncode"],0);assert_eq!(e["success"],true);for stream in["stdout","stderr"]{assert_eq!(hash(&format!("{dir}/{stream}.log")),e[format!("{stream}_sha256")].as_str().unwrap());}let c=read(&format!("{dir}/command.json"));assert_eq!(&c["argv"].as_array().unwrap()[4..],step["argv"].as_array().unwrap());if let Some(env)=c["environment"].as_object(){for(k,v)in env{assert_eq!(&step["environment"][k],v);}}e["elapsed_ms"].as_f64().unwrap()}
fn main(){let phase=std::env::args().nth(1).unwrap();assert!(["preflight","main"].contains(&phase.as_str()));let mut pin_count=0;for f in["build-pins.json","link-fixed-pins.json","capture-pins.json"]{for(p,h)in read(&format!("{R}/{f}")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap(),"{p}");pin_count+=1;}}
let mut inodes=BTreeSet::new();for c in read(&format!("{R}/copies.json")).as_array().unwrap(){let p=c["path"].as_str().unwrap();let m=fs::metadata(p).unwrap();assert_eq!(m.ino(),c["inode"].as_u64().unwrap());assert_eq!(m.dev(),c["device"].as_u64().unwrap());assert_eq!(hash(p),c["sha256"]);assert!(inodes.insert((m.dev(),m.ino())));}assert_eq!(inodes.len(),6);
let prior=if phase=="preflight"{PRIOR.to_string()}else{format!("{R}/proof-sha256-after-preflight.json")};let mut ledger=read(&prior).as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_string()).collect::<BTreeSet<_>>();let expected=if phase=="preflight"{53917}else{53926};assert_eq!(ledger.len(),expected);let before=ledger.len();let jobs=read(&format!("{R}/{phase}-jobs.json"));let plan=read(&format!("{R}/{phase}-plan.json"));let run=read(&format!("{R}/{phase}-run/result.json"));assert_eq!(run["status"],"complete");assert_eq!(jobs.as_array().unwrap().len(),if phase=="preflight"{9}else{81});let steps=plan["steps"].as_array().unwrap();assert_eq!(run["steps"],json!(steps.iter().map(|s|s["name"].as_str().unwrap()).collect::<Vec<_>>()));let mut rows=Vec::new();let mut proofs=Vec::new();let mut samples_total=0;let mut elapsed=0.;let mut verify_elapsed=0.;
for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let step=steps.iter().find(|s|s["name"]==name).unwrap();elapsed+=receipt(&format!("{R}/{phase}-run/{name}"),step);let raw=fs::read_to_string(format!("{R}/{phase}-run/{name}/stdout.log")).unwrap();let samples=raw.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();let n=j["rounds"].as_u64().unwrap()as usize;assert_eq!(samples.len(),n);let mut sum=0.;for(i,s)in samples.iter().enumerate(){assert_eq!(s["round"],i);let x=s["ms"].as_f64().unwrap();assert!(x.is_finite()&&x>0.);sum+=x;}samples_total+=n;let summaries=raw.lines().filter_map(|l|l.strip_prefix("SUMMARY ")).collect::<Vec<_>>();assert_eq!(summaries.len(),1);let s:Value=serde_json::from_str(summaries[0]).unwrap();assert_eq!(s["rounds"],n);assert_eq!(s["priming"],3);assert_eq!(s["workers"],j["case"]["workers"]);assert_eq!(s["placement_before"],s["placement_after"]);let w=s["workers"].as_u64().unwrap()as usize;let p=&s["placement_before"];assert_eq!(p["mode"],"fixed");assert_eq!(p["tasks"],w+1);assert_eq!(p["main_allowed"],json!((0..w).collect::<Vec<_>>()));assert_eq!(p["worker_rows"].as_array().unwrap().len(),w);for(i,r)in p["worker_rows"].as_array().unwrap().iter().enumerate(){assert_eq!(r["index"],i);assert_eq!(r["allowed"],json!([i]));}
let dir=j["proof_dir"].as_str().unwrap();assert_eq!(fs::metadata(format!("{dir}/0.proof")).unwrap().len(),164);let ph=hash(&format!("{dir}/0.proof"));assert!(ledger.insert(ph.clone()),"duplicate proof");let public=hash(&format!("{dir}/0.public"));assert_eq!(public,j["case"]["public_sha256"]);let vname=format!("verify-{name}");let vstep=steps.iter().find(|s|s["name"]==vname).unwrap();verify_elapsed+=receipt(&format!("{R}/{phase}-run/{vname}"),vstep);let vr=fs::read_to_string(format!("{R}/{phase}-run/{vname}/stdout.log")).unwrap();assert_eq!(vr.lines().filter(|l|l.starts_with("VERIFIED ")).count(),1);for binding in[format!("proof_sha256={ph}"),format!("public_sha256={public}"),format!("image_sha256={}",j["case"]["image_sha256"].as_str().unwrap())]{assert!(vr.contains(&binding));}proofs.push(json!({"name":name,"proof_sha256":ph,"public_sha256":public,"image_sha256":j["case"]["image_sha256"]}));rows.push(json!({"name":name,"case":j["case"]["name"],"arm":j["arm"],"block":j["block"],"backing":j["backing"],"mean_ms":sum/n as f64,"cpu_ms":(s["user_cpu_ms"].as_f64().unwrap()+s["system_cpu_ms"].as_f64().unwrap())/n as f64,"rss_mib":s["whole_process_maxrss_kib"].as_f64().unwrap()/1024.,"summary":s}));}
let ledger_name=format!("proof-sha256-after-{phase}.json");save(&ledger_name,json!(ledger));save(&format!("{phase}-rows.json"),json!(rows));save(&format!("{phase}-proofs.json"),json!(proofs));let review=json!({"passed":true,"pins_checked":pin_count,"phase":phase,"SDK_processes":jobs.as_array().unwrap().len(),"timed_samples":samples_total,"SDK_calls_including_primes":samples_total+jobs.as_array().unwrap().len()*3,"new_exports":ledger.len()-before,"ledger_before":before,"ledger_after":ledger.len(),"ledger_sha256":hash(&format!("{R}/{ledger_name}")),"capture_command_elapsed_ms":elapsed,"verifier_command_elapsed_ms":verify_elapsed});save(&format!("{phase}-review.json"),review.clone());println!("{}",review);
if phase=="main"{let mut summary=Vec::new();for case in["1x2-w16","1x2-w32","2x2-w32"]{let mut armrows=Vec::new();for arm in["REF","OFF","ON"]{let selected=rows.iter().filter(|r|r["case"]==case&&r["arm"]==arm).collect::<Vec<_>>();assert_eq!(selected.len(),9);armrows.push(json!({"arm":arm,"ms":med(selected.iter().map(|r|r["mean_ms"].as_f64().unwrap()).collect()),"cpu_ms":med(selected.iter().map(|r|r["cpu_ms"].as_f64().unwrap()).collect()),"rss_mib_max":selected.iter().map(|r|r["rss_mib"].as_f64().unwrap()).reduce(f64::max).unwrap()}));}
let mut comps=Vec::new();for denom in["OFF","REF"]{let mut ratios=Vec::new();let mut bycopy=Vec::new();for copy in 0..3{let mut cr=Vec::new();for block in 0..3{let row=|arm:&str|rows.iter().find(|r|r["case"]==case&&r["arm"]==arm&&r["backing"]==copy&&r["block"]==block).unwrap();let q=row("ON")["mean_ms"].as_f64().unwrap()/row(denom)["mean_ms"].as_f64().unwrap();cr.push(q);ratios.push(q);}bycopy.push(med(cr));}comps.push(json!({"comparison":format!("ON/{denom}"),"median_ratio":med(ratios.clone()),"per_backing_medians":bycopy,"wins":ratios.iter().filter(|&&v|v<1.).count(),"min":ratios.iter().copied().reduce(f64::min).unwrap(),"max":ratios.iter().copied().reduce(f64::max).unwrap()}));}let positive=comps.iter().all(|c|c["per_backing_medians"].as_array().unwrap().iter().all(|v|v.as_f64().unwrap()<1.));let result=json!({"case":case,"arms":armrows,"comparisons":comps,"all_backings_both_comparisons_positive":positive});println!("{}",result);summary.push(result);}save("analysis.json",json!({"summary":summary,"screen_only":true,"accepted_unchanged":true,"review":review}));}}
